// app/components/YearFilterSelector.js
'use client';
import { useYearFilter } from '../context/YearFilterSelector';

export default function YearFilterSelector() {
  const { yearFilter, setYearFilter } = useYearFilter();
  
  // Génération des années (5 dernières années)
  const years = Array.from({ length: 5 }, (_, i) => {
    const year = new Date().getFullYear() - i;
    return year.toString();
  });

  if (!yearFilter || !setYearFilter) {
    return <div>Chargement...</div>;
  }

  return (
    <select
      value={yearFilter}
      onChange={(e) => setYearFilter(e.target.value)}
      className="p-2 border rounded"
    >
      {years.map(year => (
        <option key={year} value={year}>{year}</option>
      ))}
    </select>
  );
}